import{_ as a,o as l,c as o,ac as r}from"./chunks/framework.CrIZQWiq.js";const b=JSON.parse('{"title":"leebox","description":"ai助手","frontmatter":{"tag":["vscode插件"],"title":"leebox","description":"ai助手"},"headers":[],"relativePath":"articles/产品/leebox.md","filePath":"articles/产品/leebox.md","lastUpdated":null}'),t={name:"articles/产品/leebox.md"};function i(n,e,d,h,s,c){return l(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1781410112254"},e[0]||(e[0]=[r('<h1 id="leebox-把-ai-编程助手嵌入-vs-code-侧边栏" tabindex="-1">Leebox：把 AI 编程助手嵌入 VS Code 侧边栏 <a class="header-anchor" href="#leebox-把-ai-编程助手嵌入-vs-code-侧边栏" aria-label="Permalink to &quot;Leebox：把 AI 编程助手嵌入 VS Code 侧边栏&quot;">​</a></h1><blockquote><p>不用切换窗口，不用复制粘贴，让大模型就在编辑器里陪你写代码。</p></blockquote><hr><h2 id="一句话介绍" tabindex="-1">一句话介绍 <a class="header-anchor" href="#一句话介绍" aria-label="Permalink to &quot;一句话介绍&quot;">​</a></h2><p><strong>Leebox</strong> 是一款将 AI 对话面板嵌入 VS Code 侧边栏的插件，基于 OpenRouter 平台提供多模型对话与代码编辑能力。</p><hr><h2 id="下载安装" tabindex="-1">下载安装 <a class="header-anchor" href="#下载安装" aria-label="Permalink to &quot;下载安装&quot;">​</a></h2><ul><li><strong>VS Code Marketplace</strong>：<a href="https://marketplace.visualstudio.com/items?itemName=leeb.leebox" target="_blank" rel="noreferrer">https://marketplace.visualstudio.com/items?itemName=leeb.leebox</a></li><li><strong>一键安装</strong>（需本地已安装 VS Code）：<a href="vscode:extension/leeb.leebox" target="_blank" rel="noreferrer">vscode:extension/leeb.leebox</a></li></ul><hr><h2 id="为什么需要它" tabindex="-1">为什么需要它？ <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它？&quot;">​</a></h2><p>AI 辅助编程已经成为日常，但很多人都有过这样的体验：</p><ul><li>在浏览器和编辑器之间来回切换，上下文不断被打断；</li><li>想把当前文件发给 AI，需要手动复制粘贴；</li><li>AI 生成的代码想用到项目里，又要复制、找位置、粘贴；</li><li>每个模型都要单独注册、配置 API Key，门槛不低；</li><li>希望 AI 用中文回答，却总要额外叮嘱。</li></ul><p>Leebox 的想法很直接：<strong>把 AI 无缝嵌入你的编码工作流</strong>，让它像侧边栏一样常驻，随时可用。</p><hr><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="🤖-20-内置-openrouter-免费模型" tabindex="-1">🤖 20+ 内置 OpenRouter 免费模型 <a class="header-anchor" href="#🤖-20-内置-openrouter-免费模型" aria-label="Permalink to &quot;🤖 20+ 内置 OpenRouter 免费模型&quot;">​</a></h3><p>涵盖 GPT、Claude、Kimi、Llama、GLM、Qwen、Gemma、Nemotron 等主流模型。其中实测可用的模型会标有 ⭐ 推荐，省去你一个个试错的麻烦。</p><h3 id="📄-一键引用当前文件" tabindex="-1">📄 一键引用当前文件 <a class="header-anchor" href="#📄-一键引用当前文件" aria-label="Permalink to &quot;📄 一键引用当前文件&quot;">​</a></h3><p>勾选「引用当前文件」后，Leebox 会自动把当前打开的文件内容作为上下文发送给 AI，让模型基于真实代码作答，回答更精准。</p><h3 id="✍️-代码直接应用到编辑器" tabindex="-1">✍️ 代码直接应用到编辑器 <a class="header-anchor" href="#✍️-代码直接应用到编辑器" aria-label="Permalink to &quot;✍️ 代码直接应用到编辑器&quot;">​</a></h3><p>AI 返回的代码块下方会显示操作按钮：</p><ul><li><strong>插入到光标</strong>：把代码插入当前光标位置；</li><li><strong>替换整个文件</strong>：一键用 AI 生成的新代码覆盖当前文件。</li></ul><h3 id="🖼️-多模态附件支持" tabindex="-1">🖼️ 多模态附件支持 <a class="header-anchor" href="#🖼️-多模态附件支持" aria-label="Permalink to &quot;🖼️ 多模态附件支持&quot;">​</a></h3><p>支持上传图片或文本文件作为附件：</p><ul><li>图片会自动转为 base64 dataUrl，作为视觉输入发送给模型；</li><li>文本文件可直接作为上下文补充。</li></ul><h3 id="🇨🇳-默认简体中文回答" tabindex="-1">🇨🇳 默认简体中文回答 <a class="header-anchor" href="#🇨🇳-默认简体中文回答" aria-label="Permalink to &quot;🇨🇳 默认简体中文回答&quot;">​</a></h3><p>内置系统提示要求 AI 始终使用简体中文，对中文开发者更友好。</p><h3 id="🎨-markdown-渲染" tabindex="-1">🎨 Markdown 渲染 <a class="header-anchor" href="#🎨-markdown-渲染" aria-label="Permalink to &quot;🎨 Markdown 渲染&quot;">​</a></h3><p>支持标题、粗体、斜体、行内代码、代码块、列表、链接等常见 Markdown 格式，阅读体验接近文档页面。</p><h3 id="⌨️-快捷键发送" tabindex="-1">⌨️ 快捷键发送 <a class="header-anchor" href="#⌨️-快捷键发送" aria-label="Permalink to &quot;⌨️ 快捷键发送&quot;">​</a></h3><p>输入完成后按 <code>Ctrl + Enter</code> 即可快速发送消息，不需要点按钮。</p><h3 id="🔑-可配置-api-key" tabindex="-1">🔑 可配置 API Key <a class="header-anchor" href="#🔑-可配置-api-key" aria-label="Permalink to &quot;🔑 可配置 API Key&quot;">​</a></h3><ul><li>留空即可使用插件内置的默认 Key，开箱即用；</li><li>也可以在 VS Code 设置中填入自己的 OpenRouter API Key，更灵活。</li></ul><h3 id="🖱️-拖拽上传" tabindex="-1">🖱️ 拖拽上传 <a class="header-anchor" href="#🖱️-拖拽上传" aria-label="Permalink to &quot;🖱️ 拖拽上传&quot;">​</a></h3><p>直接把文件拖到 Leebox 面板中即可添加为附件，操作自然流畅。</p><hr><h2 id="使用流程" tabindex="-1">使用流程 <a class="header-anchor" href="#使用流程" aria-label="Permalink to &quot;使用流程&quot;">​</a></h2><ol><li>点击 VS Code 左侧活动栏的 Leebox 图标，打开 AI 面板；</li><li>在下拉框中选择想使用的模型；</li><li>在输入框中描述问题或需求；</li><li>（可选）勾选「引用当前文件」，把当前编辑器内容作为上下文；</li><li>（可选）点击「上传文件/图片」，或拖拽文件添加附件；</li><li>点击「发送」或按 <code>Ctrl + Enter</code>，等待 AI 回答；</li><li>对回答中的代码块点击「插入到光标」或「替换整个文件」。</li></ol><hr><h2 id="技术亮点" tabindex="-1">技术亮点 <a class="header-anchor" href="#技术亮点" aria-label="Permalink to &quot;技术亮点&quot;">​</a></h2><ul><li><strong>纯 Webview 实现的侧边栏面板</strong>，UI 风格与 VS Code 主题保持一致；</li><li><strong>实时同步当前文件名</strong>：监听 <code>onDidChangeActiveTextEditor</code>，AI 始终知道你正在编辑哪个文件；</li><li><strong>自定义 Markdown 渲染器</strong>：逐行扫描代码块，生成带「应用」按钮的代码块组件；</li><li><strong>代码应用通过 VS Code <code>editor.edit</code> API 实现</strong>，支持插入、替换选区或全文件替换；</li><li><strong>多模态输入</strong>：图片附件读取为 base64 后作为 <code>image_url</code> 类型消息发送给 OpenRouter；</li><li><strong>内置默认 API Key</strong>，降低首次使用门槛，同时支持用户覆盖配置。</li></ul><hr><h2 id="适合谁用" tabindex="-1">适合谁用？ <a class="header-anchor" href="#适合谁用" aria-label="Permalink to &quot;适合谁用？&quot;">​</a></h2><ul><li>希望把 AI 深度集成到编码流程的开发者；</li><li>学生、独立开发者、技术爱好者；</li><li>经常需要代码重构、修 bug、加功能的程序员；</li><li>想对比多个免费模型效果的 AI 尝鲜者。</li></ul><hr><h2 id="典型场景" tabindex="-1">典型场景 <a class="header-anchor" href="#典型场景" aria-label="Permalink to &quot;典型场景&quot;">​</a></h2><ul><li>日常编码问答、算法讲解、技术概念查询；</li><li>基于当前文件进行代码重构、修 bug、加功能；</li><li>图片相关的编程辅助，例如 UI 截图分析、流程图识别；</li><li>减少上下文切换，把问答和改代码集中在同一个窗口完成。</li></ul><hr><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>Leebox 不追求成为最强大的 AI 客户端，它只专注于一件事：<strong>让 AI 离你正在写的代码更近一点</strong>。当你不需要再复制粘贴、不再需要切窗口、不再需要手动传上下文时，AI 才真正成了你工作流的一部分。</p><p>如果你也希望编辑器里常驻一个懂代码的助手，Leebox 值得一试。</p><blockquote><p>👉 <a href="https://marketplace.visualstudio.com/items?itemName=leeb.leebox" target="_blank" rel="noreferrer">点击前往 VS Code Marketplace 下载 Leebox</a></p></blockquote>',52)]))}const p=a(t,[["render",i]]);export{b as __pageData,p as default};
